import{_ as t,k as a,a6 as o,C as s,l as n,z as r,A as l,j as h}from"./chunks/framework.BZrHWrhq.js";const d="/bwe/assets/images/advanced/editing-ios-worlds/iPhone_in_Finder_locations_sidebar.png",c="/bwe/assets/images/advanced/editing-ios-worlds/iPhone_Finder_enable_Wi-Fi_access.png",p="/bwe/assets/images/advanced/editing-ios-worlds/iPhone_Finder_Files_tab_connected.png",w=JSON.parse('{"title":"Editing iPhone/iPad Worlds","description":"How to edit world from your iPhone/iPad using the app on your computer.","frontmatter":{"title":"Editing iPhone/iPad Worlds","page_title":"Editing iPhone/iPad Worlds Using Your Computer","description":"How to edit world from your iPhone/iPad using the app on your computer.","nav_order":2,"mentions":["8Crafter"]},"headers":[{"level":2,"title":"macOS","slug":"macos","link":"#macos","children":[{"level":3,"title":"Connecting using a cable","slug":"connecting-using-a-cable","link":"#connecting-using-a-cable","children":[]},{"level":3,"title":"Connecting over Wi-FI","slug":"connecting-over-wi-fi","link":"#connecting-over-wi-fi","children":[]},{"level":3,"title":"Unmounting the volumes","slug":"unmounting-the-volumes","link":"#unmounting-the-volumes","children":[]},{"level":3,"title":"Useful Scripts","slug":"useful-scripts","link":"#useful-scripts","children":[]},{"level":3,"title":"Troubleshooting","slug":"troubleshooting","link":"#troubleshooting","children":[{"level":4,"title":"The mounting commands are throwing There was an error accessing the mount point: Input/output error","slug":"the-mounting-commands-are-throwing-there-was-an-error-accessing-the-mount-point-input-output-error","link":"#the-mounting-commands-are-throwing-there-was-an-error-accessing-the-mount-point-input-output-error","children":[]},{"level":4,"title":"The mounting commands are throwing Ensure that the device is connected and usbmuxd is properly installed.","slug":"the-mounting-commands-are-throwing-ensure-that-the-device-is-connected-and-usbmuxd-is-properly-installed","link":"#the-mounting-commands-are-throwing-ensure-that-the-device-is-connected-and-usbmuxd-is-properly-installed","children":[]}]}]},{"level":2,"title":"Linux","slug":"linux","link":"#linux","children":[]},{"level":2,"title":"Windows","slug":"windows","link":"#windows","children":[]}],"relativePath":"advanced/editing-ios-worlds.md","filePath":"advanced/editing-ios-worlds.md"}'),u={name:"advanced/editing-ios-worlds.md"};function m(k,e,g,b,y,f){const i=l("template-EmptySection");return h(),a("div",null,[e[0]||(e[0]=o(`<p>With this app, it is possible to edit worlds from your iPhone or iPad using your computer without manually transferring the world files to your computer and back to your iPhone/iPad again.</p><p>On macOS it is also possible to edit your device&#39;s worlds over Wi-Fi without using a cable.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This does <strong>NOT</strong> require a jailbroken device. You can do it on any iPhone/iPad.</p></div><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>First, install Homebrew.</p><p>Then, if you have <code class="shiki"><span>osxfuse</span></code> installed, uninstall it:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">brew</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> uninstall</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> osxfuse</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then, install <code class="shiki"><span>macfuse</span></code>:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">brew</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> install</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --cask</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> macfuse</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then, install <code class="shiki"><span>ifuse</span></code>:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">brew</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> install</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> gromgit/fuse/ifuse-mac</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then, choose the commands below for your use case.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>After running these commands for the first time, you will likely see an error about needing to allow a kernel extension.</p><p>Instructions on how to do this can be found here: <a href="https://github.com/macfuse/macfuse/wiki/Getting-Started#kernel-backend" target="_blank" rel="noreferrer">https://github.com/macfuse/macfuse/wiki/Getting-Started#kernel-backend</a>.</p><p>If you can&#39;t figure out where the Startup Security Utility is, it can be accessed by going to Options in the Recovery Environment, then once you get past entering your password to continue, click <code class="shiki"><span>Utilities &gt; Startup Security Utility</span></code> in the menu bar at the top of the screen.</p><p>Once you have allowed the kernel extension and restarted your computer, you can run the commands below again and they will work as expected.</p></div><p>Below are the commands to mount the iPhone or iPad&#39;s Minecraft and Minecraft Preview documents folders.</p><p>Before running these, you will need to create the <code class="shiki"><span>~/Library/Application Support/bedrock_world_editor/mounted_volumes/iPhone-Minecraft</span></code> and/or <code class="shiki"><span>~/Library/Application Support/bedrock_world_editor/mounted_volumes/iPhone-MinecraftPreview</span></code> folders on your computer.</p><p>To get to the <code class="shiki"><span>Volumes</span></code> folder, do Shift+Command+G in Finder, then type <code class="shiki"><span>/Volumes</span></code> and press return.</p><h3 id="connecting-using-a-cable" tabindex="-1">Connecting using a cable <a class="header-anchor" href="#connecting-using-a-cable" aria-label="Permalink to &quot;Connecting using a cable&quot;">​</a></h3><p>To connect to your iPhone/iPad using a cable, use the following commands:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ifuse</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --documents</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> com.mojang.minecraftpe</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ~/Library/Application</span><span style="--shiki-light:#EE0000;--shiki-dark:#D7BA7D;">\\ </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Support/bedrock_world_editor/mounted_volumes/iPhone-Minecraft</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ifuse</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --documents</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> com.mojang.minecraftpreview</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ~/Library/Application</span><span style="--shiki-light:#EE0000;--shiki-dark:#D7BA7D;">\\ </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Support/bedrock_world_editor/mounted_volumes/iPhone-MinecraftPreview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="connecting-over-wi-fi" tabindex="-1">Connecting over Wi-FI <a class="header-anchor" href="#connecting-over-wi-fi" aria-label="Permalink to &quot;Connecting over Wi-FI&quot;">​</a></h3><p>To allow your iPhone/iPad to connect over Wi-Fi do the following (these steps only need to be done the first time):</p><ol><li><p>Connect your iPhone/iPad to your computer with a cable</p></li><li><p>Go to Finder.</p></li><li><p>Click on your iPhone/iPad in Locations section of the sidebar.</p><p><img src="`+d+'" alt="iPhone in the Locations section of the sidebar"></p></li><li><p>Scroll down to the bottom of the General tab and check &quot;Show this iPhone when on Wi-Fi&quot;.</p><p><img src="'+c+'" alt="Show this iPhone when on Wi-Fi option checked at the bottom of the General tab"></p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If the below commands say:<br><code class="shiki"><span>ERROR: No device found! Ensure that the device is connected and usbmuxd is properly installed.</span></code><br> then you may need to go into Finder and click on your iPhone/iPad in the Locations section of the sidebar to make it connect.</p></div><p>To connect to your iPhone/iPad over Wi-Fi, use the following commands:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ifuse</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -n</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --documents</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> com.mojang.minecraftpe</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ~/Library/Application</span><span style="--shiki-light:#EE0000;--shiki-dark:#D7BA7D;">\\ </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Support/bedrock_world_editor/mounted_volumes/iPhone-Minecraft</span></span>\n<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ifuse</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -n</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --documents</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> com.mojang.minecraftpreview</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ~/Library/Application</span><span style="--shiki-light:#EE0000;--shiki-dark:#D7BA7D;">\\ </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Support/bedrock_world_editor/mounted_volumes/iPhone-MinecraftPreview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If you have multiple devices connected to your computer over Wi-Fi, you can use the <code class="shiki"><span>-u</span></code> flag to specify a specific device by UDID.</p><p>Example:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ifuse</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -u</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 00008030-0000000000000000</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --documents</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> com.mojang.minecraftpe</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ~/Library/Application</span><span style="--shiki-light:#EE0000;--shiki-dark:#D7BA7D;">\\ </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Support/bedrock_world_editor/mounted_volumes/iPhone1-Minecraft</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>You can get the device&#39;s UDID by using the following command:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">idevice_id</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>It will output a list of the UDIDs of all the connected devices.</p><p>You can then use the following command to get the names of the devices that each UDID corresponds to:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">idevicename</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -n</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -u</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 00008030-0000000000000000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>You can access worlds from multiple devices at once if you mount each of them to different folders in the <code class="shiki"><span>/Volumes</span></code> folder.</p><hr><p>To see your iPhone/iPad&#39;s worlds in the app, click on the &quot;Show more&quot; button at the bottom of the world list.</p><p>It may take a 1-30 seconds for your worlds to appear.</p><p>The following factors affect how long it takes:</p><ul><li>How may worlds you have on your iPhone/iPad.</li><li>Your Wi-Fi connection (if you are connected over Wi-Fi).</li><li>The quality of the cable you are using (if you are using a cable).</li><li>If the cable is USB-C or USB-A (USB-C is faster) (if you are using a cable).</li><li>If the cable is connected to one of your Mac&#39;s Thunderbolt ports (this makes it faster) (if you are using a cable).</li><li>If the cable is connected directly to your Mac or to a hub (directly to the Mac is faster) (if you are using a cable).</li><li>The speed of your Mac (minimal impact).</li><li>The speed of your iPhone/iPad (minimal impact unless your phone is really old, and thus has a slow connection to your Mac).</li></ul><h3 id="unmounting-the-volumes" tabindex="-1">Unmounting the volumes <a class="header-anchor" href="#unmounting-the-volumes" aria-label="Permalink to &quot;Unmounting the volumes&quot;">​</a></h3><p>If your iPhone/iPad gets disconnected and you don&#39;t want to restart your computer before reconnecting it, you can unmount the volumes using the following commands to allow you to remount it:</p><div class="language-zsh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">zsh</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">umount</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ~/Library/Application</span><span style="--shiki-light:#EE0000;--shiki-dark:#D7BA7D;">\\ </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Support/bedrock_world_editor/mounted_volumes/iPhone-Minecraft</span></span>\n<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">umount</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ~/Library/Application</span><span style="--shiki-light:#EE0000;--shiki-dark:#D7BA7D;">\\ </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Support/bedrock_world_editor/mounted_volumes/iPhone-MinecraftPreview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="useful-scripts" tabindex="-1">Useful Scripts <a class="header-anchor" href="#useful-scripts" aria-label="Permalink to &quot;Useful Scripts&quot;">​</a></h3><p>There are some premade script files to mount/unmount/remount the volumes for your iPhone/iPad&#39;s Minecraft and Minecraft Preview documents folders.</p><p>You can find them <a href="https://github.com/8Crafter-Studios/Bedrock-World-Editor/raw/refs/heads/main/.github/assets/scripts/macOS_iPhone_Minecraft_mounting_scripts.zip" target="_blank" rel="noreferrer">here</a>.</p><p>These scripts also handle creating the folders for the volumes.</p><p>Make sure you configure <code class="shiki"><span>.sh</span></code> files to open with Terminal by default, so you can run the scripts by double clicking them.</p><ul><li><code class="shiki"><span>mount_iPhone_Minecraft_wired.sh</span></code> - Mounts the volumes using a wired connection.</li><li><code class="shiki"><span>mount_iPhone_Minecraft_Wi-Fi.sh</span></code> - Mounts the volumes over Wi-Fi.</li><li><code class="shiki"><span>remount_iPhone_Minecraft_wired.sh</span></code> - Unmounts the volumes, then mounts them again using a wired connection. Useful if your iPhone/iPad gets disconnected, you can run this and it will reconnect it. This is also useful to quickly switch from Wi-Fi to a wired connection.</li><li><code class="shiki"><span>remount_iPhone_Minecraft_Wi-Fi.sh</span></code> - Unmounts the volumes, then mounts them again using Wi-Fi. Useful if your iPhone/iPad gets disconnected, you can run this and it will reconnect it. This is also useful to quickly switch from a wired connection to Wi-Fi.</li><li><code class="shiki"><span>unmount_iPhone_Minecraft.sh</span></code> - Unmounts the volumes.</li></ul><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><hr><h4 id="the-mounting-commands-are-throwing-there-was-an-error-accessing-the-mount-point-input-output-error" tabindex="-1">The mounting commands are throwing <code class="shiki"><span>There was an error accessing the mount point: Input/output error</span></code> <a class="header-anchor" href="#the-mounting-commands-are-throwing-there-was-an-error-accessing-the-mount-point-input-output-error" aria-label="Permalink to &quot;The mounting commands are throwing `There was an error accessing the mount point: Input/output error`&quot;">​</a></h4><p>If you get this error, you need to unmount the volume first. See <a href="#unmounting-the-volumes">Unmounting the volumes</a>.</p><hr><h4 id="the-mounting-commands-are-throwing-ensure-that-the-device-is-connected-and-usbmuxd-is-properly-installed" tabindex="-1">The mounting commands are throwing <code class="shiki"><span>Ensure that the device is connected and usbmuxd is properly installed.</span></code> <a class="header-anchor" href="#the-mounting-commands-are-throwing-ensure-that-the-device-is-connected-and-usbmuxd-is-properly-installed" aria-label="Permalink to &quot;The mounting commands are throwing `Ensure that the device is connected and usbmuxd is properly installed.`&quot;">​</a></h4><p>Try running the commands again after a few seconds.</p><p>If that doesn&#39;t work, try turning your computer&#39;s Wi-Fi off and back on.</p><p>If that doesn&#39;t work, try turning your iPhone/iPad&#39;s Wi-Fi off and back on.</p><p>If that doesn&#39;t work, try the below instructions.</p><p>If you are connecting with a cable, make sure the iPhone/iPad is showing up in the Locations section of the left sidebar in Finder. If not, double check that your iPhone/iPad is connected properly.</p><p>If you are connecting over Wi-Fi, make sure your iPhone/iPad is showing up in the Locations section of the left sidebar in Finder. If not, follow the instructions above to allow your iPhone/iPad to connect over Wi-Fi. If your iPhone/iPad is showing up in the Locations section of the left sidebar in Finder, then click on your iPhone/iPad in Finder and go to the Files tab and make sure it isn&#39;t empty.<br> It should look like this:<br><img src="'+p+'" alt="iPhone Finder Files tab with app data in the list"><br> If it is empty, then your iPhone/iPad isn&#39;t connected.<br> Try making sure no Finder windows have your iPhone/iPad open, then turn your computer&#39;s Wi-Fi off and back on, then click on your iPhone/iPad in Finder again.<br> This should cause it to reconnect and show app data in the Files tab after 1-30 seconds.<br> If it still doesn&#39;t connect, connect the cable to your Mac and go to the Files tab, then switch off of the iPhone/iPad in Finder, unplug the cable, then go back to your iPhone/iPad in Finder and try again.<br> If that didn&#39;t work, do it again but click the eject button next to your iPhone/iPad in Finder first.</p><p>If none of that works, make sure <code class="shiki"><span>usbmuxd</span></code> is properly installed.</p><hr><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2>',63)),s(i),e[1]||(e[1]=n("h2",{id:"windows",tabindex:"-1"},[r("Windows "),n("a",{class:"header-anchor",href:"#windows","aria-label":'Permalink to "Windows"'},"​")],-1)),s(i)])}const P=t(u,[["render",m]]);export{w as __pageData,P as default};
